package io.github.marcel_park.mealtracker.model;

import jakarta.persistence.*;

// A named amount of a food, e.g. "Packung" = 250 g. Items can be booked as a number of it (see
// Quantity); their amount follows the portion's. A portion belongs to exactly one food and is
// edited together with it, see FoodService.
@Entity
// Mirrors the unique key of the V6 migration, so schemas generated by Hibernate (tests) have it too.
@Table(name = "food_portion",
        uniqueConstraints = @UniqueConstraint(name = "uq_food_portion_name", columnNames = {"food_id", "name"}))
public class FoodPortion {

    // Same limit as the database column; the app keeps names short enough for one search row.
    public static final int MAX_NAME_LENGTH = 20;

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "food_id", nullable = false)
    private Food food;

    @Column(nullable = false, length = MAX_NAME_LENGTH)
    private String name;

    // In the unit of the food.
    @Column(nullable = false)
    private double amount;

    // The default portion when booking the food. FoodService keeps exactly one per food.
    @Column(name = "is_favorite", nullable = false)
    private boolean favorite;

    protected FoodPortion() {}

    FoodPortion(Food food, String name, double amount, boolean favorite) {
        this.food = food;
        this.name = name;
        this.amount = amount;
        this.favorite = favorite;
    }

    public Long getId() { return id; }
    public Food getFood() { return food; }
    public String getName() { return name; }
    public void setName(String name) { this.name = name; }
    public double getAmount() { return amount; }
    public void setAmount(double amount) { this.amount = amount; }
    public boolean isFavorite() { return favorite; }
    public void setFavorite(boolean favorite) { this.favorite = favorite; }
}
